aux=old['auxiliary_read_sha256']
assert all(sha(ROOT/n)==h for n,h in {**guards,**aux}.items())
assert all(sha(HERE/n)==h for n,h in old['evidence_sha256'].items())
shared=old['shared_working_file_sha256'];doc=ROOT/old['document']['path'];prefix=doc.read_bytes();assert sha(doc)==old['document']['sha256']
assert all(sha(ROOT/n)==h for n,h in shared.items() if n!=old['document']['path'])
index=Path(git('rev-parse','--git-path','index'));index=index if index.is_absolute() else ROOT/index;index_hash=sha(index);assert index_hash==old['git_index_sha256']
inv,cov=load('source_inventory.json'),load('read_coverage.json');assert inv['commit']==head and load('pending_read.json')==[]
assert all(sha(ROOT/n)==v['sha256'] for n,v in inv['files'].items())
stats=json.loads(subprocess.check_output(['python',str(HERE/'read_coverage.py'),'status'],cwd=ROOT));assert stats['complete_files']==2392 and stats['read_chars']==27857944 and len(stats['changed_since_inventory'])==24 and not stats['pending_chunks']
reread=sorted(set(old['coverage']['changed_since_inventory'])-set(stats['changed_since_inventory']))
assert len(reread)==20 and sum(inv['files'][n]['chars'] for n in reread)==314824
assert all(cov[n]['sha256']==inv['files'][n]['sha256'] and cov[n]['through']==inv['files'][n]['chars'] for n in reread)
area='crates/cambium/';files=[n for n in inv['files'] if n.startswith(area)]
assert len(files)==434 and sum(inv['files'][n]['chars'] for n in files)==5313101
assert all(cov[n]['sha256']==inv['files'][n]['sha256'] and cov[n]['through']==inv['files'][n]['chars'] for n in files)
lock=tomllib.loads((ROOT/'Cargo.lock').read_text())['package']
genet=sorted({p['source'] for p in lock if 'merely-made/genet.git' in p.get('source','')})
netrender=sorted({p['source'] for p in lock if 'merely-made/netrender.git' in p.get('source','')})
assert len(genet)==len(netrender)==1 and genet[0].endswith('#7f13b85f53c48fa90f433a6cd2ad45cd744e8b02') and netrender[0].endswith('#e8cda06efc11c11595f2fa1bb30bce7e72979537')
traces=[]
for title,path,start,end,required in [
 ('Reconfiguration has no presentation output','crates/cambium/cambium-rootstock/src/presentation/wgpu.rs','            genet_render_host::SurfaceAcquire::Reconfigured => {','            genet_render_host::SurfaceAcquire::Unavailable', ['return Ok(None)']),
 ('Native host returns before presentation sequence mutation','crates/cambium/cambium-rootstock/src/frame.rs','        let output = match output {','        let crate::presentation::wgpu::WgpuOutput', ['Ok(None)', 'return;', 'Err(failure)']),
 ('Wgpu driver stamps only a real presenter output','crates/cambium/cambium-rootstock/src/presentation/wgpu_driver.rs','        self.profile = Some(profile);','    fn take_profile(', ['let Some(output) = result? else', 'return Ok(None)', 'Ok(Some(stamp))']),
 ('Installed driver host returns before recording a missing output','crates/cambium/cambium-rootstock/src/presentation/drive.rs','        let presented = match result {','        self.s.last_presentation_failure = None;', ['Ok(None)', 'return;', 'driver returned a foreign presentation identity']),
 ('Direct harness resolver uses retained semantics','crates/cambium/cambium-genet-winit-host/src/harness.rs','    fn resolve_node(', '\n    /// Move the cursor:', ['document_projection(', 'matching_prefer_exact_with_projection(', 'layout.rendered_visible']),
 ('Native host policy surrounds runner key dispatch','crates/cambium/cambium-rootstock/src/input.rs','    pub fn key(&mut self, press:', '\n    /// The host\'s own zoom chords:', ['key_intercept', 'zoom_chord', 'runner.dispatch_key', 'move_focused_text_visual']),
]:
 s=(ROOT/path).read_text();first=s.index(start);last=s.index(end,first);excerpt=s[first:last];assert all(n in excerpt for n in required),title
 traces.append({'title':title,'path':path,'source_sha256':sha(ROOT/path),'first_line':s[:first].count('\n')+1,'last_line':s[:last].count('\n')+1,'excerpt':excerpt})
trace_name='upstream_cambium_source_traces.json';assert not (HERE/trace_name).exists()
save(trace_name,{'qualification':'Exact current source traces only. Current touched files fully reread; unchanged neighboring host callers were previously fully read and retraced here. No compiled/OS/GPU/presentation proof.','traces':traces})
notes,authority=load('review_notes.json'),load('authority_map.json');assert notes['findings'][-1]['id']=='Q350' and authority['entries'][-1]['id']=='A954'
rows=[
 ('Root manifest claims more path centralization than it implements','Cargo.toml says every member inherits internal paths so only the root knows where each crate lives.', ['Cargo.toml','crates/cambium/cambium-genet-winit-host/Cargo.toml','crates/cambium/mesquite/Cargo.toml'],'The reread host and Mesquite manifests still repeat meristem/cambium/rootstock/sprigging paths and versions instead of inheriting those entries. They currently agree and name the same in-tree crates; this is duplicated configuration and an inaccurate exclusivity comment, not demonstrated duplicate runtime package identity.'),
 ('Supplier identity is lockfile evidence rather than a prose revision list','Workspace dependencies and root patches select one Genet and one Netrender source in the current lock.', ['Cargo.toml'],'Cargo.lock contains Genet7f13b85f and Netrender e8cda06e once per source. Netrender now uses an explicit revision while the first-party branch convention comment remains broad. Long migration comments still describe Armillary/scenes as standalone git siblings and consumers taking this host from genet.git despite current path members. Record the drift without treating the comments as live dependency resolution or a fresh Cargo graph build.'),
 ('Checked presentation reconfiguration does not become a successful frame','WgpuPresentation returns Ok(None) on SurfaceAcquire::Reconfigured.', ['crates/cambium/cambium-rootstock/src/presentation/wgpu.rs','crates/cambium/cambium-rootstock/src/presentation/wgpu_driver.rs','crates/cambium/cambium-rootstock/src/presentation/drive.rs','crates/cambium/cambium-rootstock/src/frame.rs'],'Both ordinary-native and installed-driver host routes return before presentation_sequence, last_redraw_presentation, observer and capture completion. WgpuDriver stamps only Some(output). The shared WgpuPresentation is actual reused raster/acquire/compose implementation. Raster work precedes acquire, but that is not a false presentation claim. Source traces only; no headed reset/reconfigure receipt.'),
 ('Renderer access differs intentionally between native and browser targets','Surface::renderer is now native-only, while try_renderer remains portable.', ['crates/cambium/cambium-rootstock/src/lib.rs','crates/cambium/cambium-rootstock/src/presentation/wgpu.rs'],'Browser try_renderer delegates to the shared Core frame gate; native returns a renderer borrow. Typed acquire and post-compose checks detect device loss in the presenter. Do not describe every native try_renderer call itself as a device-loss refusal, or equate a compile gate with a GPU/device recovery run.'),
 ('Direct harness targeting now shares retained semantic names','Harness::resolve_node builds the same document_projection used by accessibility.', ['crates/cambium/cambium-genet-winit-host/src/harness.rs','crates/cambium/cambium-genet-winit-host/tests/scenario.rs','crates/cambium/cambium-rootstock/src/lib.rs'],'matching_prefer_exact_with_projection, rendered visibility and retained painted bounds drive direct clicks. Tests explicitly preserve aria-labelledby precedence, reject raw/stale role labels and retain class selector DOM-text semantics. The with_surfaces doc still suggests generic resolve works unchanged although it supplies only DOM/sheet; the maintained direct resolver is the actual retained path. Tests read, not rerun.'),
 ('Estimated fixture matching is no longer presented as retained selector authority','Changed tests explicitly opt into matching_estimated_fixture and its feature.', ['crates/cambium/cambium-genet-winit-host/Cargo.toml','crates/cambium/cambium-genet-winit-host/tests/ui_zoom.rs','crates/cambium/mesquite/Cargo.toml','crates/cambium/tabard-workshop/Cargo.toml','crates/cambium/tabard-workshop/tests/release_host_acceptance.rs'],'Those queries mostly locate test nodes; pointer geometry then comes from Harness painted/visible rect and dispatch from its shared host. Native header tests use retained projection directly. Renaming fixture APIs helps attribution but does not independently establish accessible-name parity for every estimated lookup.'),
 ('Scenario key verbs exercise a narrower route than native host keys','Mesquite sends key/input-text events directly to the retained runner.', ['crates/cambium/mesquite/src/probe.rs','crates/cambium/cambium-rootstock/src/input.rs','crates/cambium/cambium-genet-winit-host/src/harness.rs'],'Native Host::key runs held-Tab spatial mode, application key_intercept, zoom policy and visual-caret work around runner dispatch. Harness::press_key calls that owner; Mesquite key/input-text do not. This is a source-proven test-scope distinction, not a new demonstration of failed ordinary button activation. Existing Q326 wheel-surface issue remains unchanged on the Mere side; the newly pinned external selector implementation was not rebuilt/retraced here.'),
 ('Workshop native binding keeps application and host policy separate','native_hooks calls shared control synchronization/export and delegates dirty-close to WorkshopState.', ['crates/cambium/tabard-workshop/src/native_host.rs','crates/cambium/tabard-workshop/tests/release_host_acceptance.rs','crates/cambium/tabard-workshop/tests/shared_components.rs'],'Current reread tests keep active theme authority separate from draft/preview edits and distinguish Focus, Click and SetValue. Existing Q328 export-policy loss on library reopen and Q329 repeated graph-leaf replacement are not fixed by these selector-only updates. They retain their prior source qualifications, not a newly executed native receipt.'),
 ('Workshop color checks use several different evidence strengths','surface.rs specimen_color reads inline declarations plus nonempty layout; usability.rs separately resolves computed styles.', ['crates/cambium/tabard-workshop/tests/surface.rs','crates/cambium/tabard-workshop/tests/usability.rs','crates/cambium/tabard-workshop/tests/instrument.rs'],'Inline declaration changes do not alone prove final computed paint or pixels. Computed-style assertions are stronger for CSS precedence but still not headed output; release_host_acceptance explicitly says it supplies neither presented-frame nor reset evidence. Shared production control routing is real reuse, while test-local traversal/declaration helpers remain duplicated.'),
]
entries=[{'id':f'A{955+i}','domain':d,'claim':c,'implementations':paths,'assessment':a,'state':'current whole-file Cambium reread; source traces only; no fresh Cargo/native/GPU execution','verification':NAME} for i,(d,c,paths,a) in enumerate(rows)];authority['entries'].extend(entries)
areas=[{'prefix':area,'files':434,'chars':5313101,'verification':NAME,'basis_commit':head,'qualification':'All434current Cambium inventory files have complete matching-hash reads;19changed files fully reread. Whole source review only.'}]
